def apply_method(self, r, **args):

    method = r.method

    # Check for record ID
    user_id = r.id
    if not user_id:
        r.error(400, current.ERROR.BAD_RECORD)

    # TODO consider to redirect to the record
    self.next = URL(args=[], vars={})

    if method == "disable":
        self.disable_user(r, **args)
    elif method == "enable":
        self.enable_user(r, **args)
    elif method == "approve":
        self.approve_user(r, **args)
    elif method == "link":
        self.link_user(r, **args)
    else:
        r.error(405, current.ERROR.BAD_METHOD)

    # TODO refactor as strict POST
    if r.http != "POST":
        redirect(self.next)

    return current.xml.json_message()

def apply_method(self, r, **attr):
    """
        Apply methods

        Args:
            r: the CRUDRequest
            attr: controller parameters
    """

    http, method = r.http, r.method
    if not method:
        if http == "GET":
            output = self.get_tree(r, **attr)
        elif r.http in ("PUT", "POST"):
            output = self.put_tree(r, **attr)
        # TODO support DELETE
        #elif r.http == "DELETE"
        #    output = self.delete(r, **attr)
        else:
            r.error(405, current.ERROR.BAD_METHOD)

    elif method == "fields":
        if http == "GET":
            output = self.get_fields(r, **attr)
        else:
            r.error(405, current.ERROR.BAD_METHOD)

    elif method == "options":
        if http == "GET":
            output = self.get_options(r, **attr)
        else:
            r.error(405, current.ERROR.BAD_METHOD)

    else:
        r.error(404, current.ERROR.BAD_ENDPOINT)

    return output
